sp_widget.client_script:
api.controller = function($scope, $interval) {
  var c = this;

  // Track upload state per document
  c.uploadingDoc = null;
  c.uploadSuccess = null;
  c.uploadError = null;

  // File selection for a specific rejected document
  c.triggerFileSelect = function(doc) {
    // Reset messages
    c.uploadSuccess = null;
    c.uploadError = null;
    // Programmatically click the hidden file input for this doc
    var fileInput = document.getElementById('reupload-' + doc.sys_id);
    if (fileInput) {
      fileInput.click();
    }
  };

  // Handle file selection and upload
  c.handleFileChange = function(doc, files) {
    if (!files || files.length === 0) return;
    var file = files[0];

    // Validate file type
    var allowedTypes = ['application/pdf', 'image/jpeg', 'image/png', 'image/jpg'];
    if (allowedTypes.indexOf(file.type) === -1) {
      c.uploadError = 'Invalid file type. Please upload a PDF or image file.';
      $scope.$apply();
      return;
    }

    // Validate file size (max 10MB)
    if (file.size > 10 * 1024 * 1024) {
      c.uploadError = 'File too large. Maximum size is 10MB.';
      $scope.$apply();
      return;
    }

    c.uploadingDoc = doc.sys_id;
    $scope.$apply();

    // Read file as base64
    var reader = new FileReader();
    reader.onload = function(e) {
      var base64 = e.target.result.split(',')[1]; // Remove data:...;base64, prefix

      c.server.get({
        action: 'reupload_document',
        docSysId: doc.sys_id,
        fileName: file.name,
        fileType: file.type,
        base64: base64
      }).then(function(response) {
        c.uploadingDoc = null;
        if (response.data.reuploadResult === 'success') {
          c.uploadSuccess = response.data.reuploadMessage || 'Document re-uploaded successfully.';
          c.uploadError = null;
          // Refresh the entire data object
          c.data = response.data;
        } else {
          c.uploadError = response.data.reuploadMessage || 'Upload failed. Please try again.';
          c.uploadSuccess = null;
        }
      }, function() {
        c.uploadingDoc = null;
        c.uploadError = 'Network error. Please try again.';
      });
    };
    reader.onerror = function() {
      c.uploadingDoc = null;
      c.uploadError = 'Could not read file. Please try again.';
      $scope.$apply();
    };
    reader.readAsDataURL(file);
  };

  // Auto-refresh polling (keep existing)
  if (c.data && c.data.hasRecord) {
    var timer = $interval(function() {
      if (!c.uploadingDoc) { // Don't refresh during upload
        c.server.get({ action: 'refreshStatus' }).then(function(response) {
          if (!c.uploadingDoc) { // Double-check still not uploading
            c.data = response.data;
          }
        });
      }
    }, 20000);
    $scope.$on('$destroy', function() { $interval.cancel(timer); });
  }
};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@500;600&display=swap');

/* Master Design Tokens */
$page-bg: #eef4f7;           // Subtle ice-slate cool tint matching teal
$card-bg: #ffffff;           // Crisp white cards
$brand-teal: #005f73;        // Deep Petrol
$brand-teal-deep: #0a4350;
$brand-blue: #0284c7;        // Sky Blue Accent
$brand-blue-hover: #0369a1;
$accent-sky: #38bdf8;
$border-light: #d8e2ea;      // Soft cool-gray borders
$border-subtle: #edf2f7;
$text-dark: #0f172a;
$text-body: #334155;
$text-muted: #64748b;
$success-green: #10b981;
$warning-amber: #d97706;

/* Outer Screen Wrapper */
.gvft-status-container {
  background-color: $page-bg;
  color: $text-body;
  min-height: 100vh;
  padding: 36px 24px 80px 24px;
  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-sizing: border-box;
}

.status-content {
  max-width: 1080px;
  width: 100%;
  margin: 0 auto;
}

/* ================= 1. Integrated Hero Header ================= */
.status-header {
  background: $card-bg;
  border: 1px solid $border-light;
  border-radius: 14px;
  padding: 24px 30px;
  margin-bottom: 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
}

.badge-case {
  background: #e0f2fe;
  color: $brand-teal;
  border: 1px solid #bae6fd;
  padding: 4px 10px;
  font-weight: 700;
  border-radius: 6px;
  font-size: 12px;
  letter-spacing: 0.4px;
  display: inline-block;
  margin-bottom: 6px;
}

.applicant-name {
  font-size: 26px;
  font-weight: 800;
  margin: 0 0 4px 0;
  color: $text-dark;
  letter-spacing: -0.5px;
}

.role-sub {
  color: $text-muted;
  font-size: 13.5px;
  margin: 0;

  strong {
    color: $text-dark;
    font-weight: 600;
  }
}

.bullet-sep {
  margin: 0 8px;
  color: #cbd5e1;
}

.status-pill {
  padding: 7px 18px;
  border-radius: 30px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  background: #f1f5f9;
  color: $text-body;
  border: 1px solid $border-light;
}

.status-submitted,
.status-open {
  background-color: #ecfeff !important;
  color: $brand-teal !important;
  border-color: #a5f3fc !important;
}

.status-under_review,
.status-pending {
  background-color: #fffbeb !important;
  color: $warning-amber !important;
  border-color: #fef3c7 !important;
}

.status-pre_approved,
.status-approved,
.status-closed_complete {
  background-color: #ecfdf5 !important;
  color: #059669 !important;
  border-color: #a7f3d0 !important;
}

/* ================= 2. Petrol/Teal Progress Banner ================= */
.progress-section-card {
  background: linear-gradient(135deg, $brand-teal 0%, $brand-teal-deep 100%) !important;
  border: 1px solid rgba(255, 255, 255, 0.1) !important;
  border-radius: 14px;
  padding: 26px 32px 22px 32px;
  margin-bottom: 20px;
  box-shadow: 0 10px 24px rgba(0, 95, 115, 0.18);
  color: #ffffff !important;
  position: relative;
  overflow: hidden;

  &::after {
    content: '';
    position: absolute;
    top: -50%;
    right: -10%;
    width: 300px;
    height: 300px;
    background: radial-gradient(circle, rgba(56, 189, 248, 0.15) 0%, transparent 70%);
    pointer-events: none;
  }
}

.progress-header-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.progress-title {
  font-size: 15px;
  font-weight: 700;
  color: #ffffff;
  display: flex;
  align-items: center;
  gap: 8px;

  i {
    color: $accent-sky;
    font-size: 16px;
  }
}

.percentage-badge {
  background: rgba(255, 255, 255, 0.15) !important;
  backdrop-filter: blur(8px);
  color: #ffffff !important;
  font-weight: 700;
  font-size: 12.5px;
  padding: 5px 14px;
  border-radius: 20px;
  border: 1px solid rgba(255, 255, 255, 0.22);
}

.progress-bar-track {
  height: 7px;
  background: rgba(0, 0, 0, 0.28);
  border-radius: 10px;
  overflow: hidden;
  margin-bottom: 26px;
}

.progress-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #38bdf8, #22d3ee);
  border-radius: 10px;
  transition: width 0.7s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Stepper Nodes */
.stages-wrapper {
  display: flex;
  justify-content: space-between;
}

.stage-node {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 135px;
  position: relative;
}

.node-circle {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
  border: 2px solid rgba(255, 255, 255, 0.25);
  color: #cbd5e1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12.5px;
  font-weight: 700;
  margin-bottom: 8px;
  transition: all 0.3s ease;
}

.stage-node.active .node-circle {
  background: $accent-sky !important;
  color: #042f2e !important;
  border-color: $accent-sky !important;
  box-shadow: 0 0 14px rgba(56, 189, 248, 0.45);
}

.stage-node.current .node-circle {
  box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.25);
}

.node-title {
  font-size: 12px;
  color: #cbd5e1;
  text-align: center;
  font-weight: 500;
  line-height: 1.35;
}

.stage-node.active .node-title {
  color: #ffffff;
  font-weight: 600;
}

/* ================= 3. Metrics Grid ================= */
.metrics-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 20px;
}

.metric-card {
  background: $card-bg;
  border: 1px solid $border-light;
  border-radius: 12px;
  padding: 16px 20px;
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.03);
  transition: transform 0.15s ease, box-shadow 0.15s ease;

  &:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.06);
  }

  label {
    display: block;
    font-size: 11px;
    text-transform: uppercase;
    color: $text-muted;
    font-weight: 700;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
  }
}

.metric-value {
  font-size: 15.5px;
  font-weight: 700;
  color: $text-dark;
  letter-spacing: -0.2px;
}

.text-success { color: $success-green !important; }
.text-warning { color: $warning-amber !important; }
.code-font {
  font-family: 'JetBrains Mono', monospace !important;
  font-size: 13.5px !important;
  color: $brand-teal !important;
}
.uppercase {
  font-family: 'JetBrains Mono', monospace !important;
  letter-spacing: 0.5px;
}

/* ================= 4. Verification Matrix Table ================= */
.checklist-card {
  background: $card-bg;
  border: 1px solid $border-light;
  border-radius: 14px;
  padding: 24px 28px;
  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
}

.checklist-title {
  font-size: 16.5px;
  font-weight: 700;
  margin: 0 0 16px 0;
  color: $brand-teal;
  display: flex;
  align-items: center;
  gap: 8px;

  i {
    color: $brand-blue;
    font-size: 18px;
  }
}

.custom-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;

  th {
    color: $text-muted;
    font-size: 11.5px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    border-bottom: 1px solid $border-light;
    padding: 12px 16px;
    background-color: #f8fafc;

    &:first-child { border-top-left-radius: 8px; }
    &:last-child { border-top-right-radius: 8px; }
  }

  td {
    padding: 14px 16px;
    border-bottom: 1px solid $border-subtle;
    font-size: 13.5px;
    color: $text-body;
    vertical-align: middle;

    strong {
      color: $text-dark;
      font-weight: 600;
    }
  }

  tbody tr:last-child td {
    border-bottom: none;
  }

  tbody tr:hover {
    background-color: #f8fafc;
  }
}

/* Badges */
.label-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 600;

  i {
    font-size: 11px;
  }
}

.status-verified, 
.status-approved {
  background: #ecfdf5;
  color: #059669;
  border: 1px solid #a7f3d0;
}

.status-submitted, 
.status-pending, 
.status-in_review {
  background: #f0fdfa;
  color: $brand-teal;
  border: 1px solid #ccfbf1;
}

.status-uploaded {
  background: #f0f9ff;
  color: $brand-blue;
  border: 1px solid #bae6fd;
}

.status-rejected {
  background: #fef2f2;
  color: #dc2626;
  border: 1px solid #fecaca;
}

.review-notes-cell {
  font-size: 13px;
  color: #64748b;
}

/* Re-upload Styles */
.reupload-btn {
  background: #e0f2fe;
  color: $brand-blue;
  border: 1px solid #bae6fd;
  padding: 6px 14px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;

  &:hover {
    background: $brand-blue;
    color: #ffffff;
  }

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
}

.upload-spinner {
  display: inline-block;
  width: 14px;
  height: 14px;
  border: 2px solid #bae6fd;
  border-top-color: $brand-blue;
  border-radius: 50%;
  animation: spin 0.6s linear infinite;
  margin-right: 6px;
  vertical-align: middle;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.action-cell {
  text-align: center;
  vertical-align: middle;
}

.action-check {
  color: #cbd5e1;
  font-size: 14px;
}

.upload-alert {
  padding: 12px 18px;
  border-radius: 8px;
  font-size: 13px;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.upload-alert-success {
  background: #ecfdf5;
  color: #059669;
  border: 1px solid #a7f3d0;
}

.upload-alert-error {
  background: #fef2f2;
  color: #dc2626;
  border: 1px solid #fecaca;
}

.file-input-hidden {
  display: none;
}

/* ================= 5. Empty State ================= */
.empty-state-card {
  background: $card-bg;
  border: 1px solid $border-light;
  border-radius: 14px;
  box-shadow: 0 4px 20px rgba(15, 23, 42, 0.04);
  text-align: center;
  padding: 80px 20px;
  max-width: 600px;
  margin: 40px auto 0 auto;
}

.empty-icon {
  font-size: 54px;
  color: #cbd5e1;
  margin-bottom: 16px;
}

.empty-title {
  font-size: 22px;
  font-weight: 700;
  color: $text-dark;
  margin-bottom: 8px;
}

.empty-desc {
  font-size: 14px;
  color: $text-muted;
  margin-bottom: 24px;
}

.btn-start {
  background: $brand-blue;
  color: #ffffff;
  font-weight: 600;
  padding: 10px 24px;
  border-radius: 8px;
  text-decoration: none;
  display: inline-block;
  transition: background 0.2s ease;

  &:hover {
    background: $brand-blue-hover;
    color: #ffffff;
  }
}

sp_widget.script:
(function() {
  var caseTable = 'x_2023506_german_1_imm_case';
  var docTable  = 'x_2023506_german_1_case_doc';

  // ── DOC_NAME_MAP fallback for getDisplayValue quirks ──
  var DOC_NAME_MAP = {
      '1': 'Passport', '2': 'Passport Photo', '3': 'Job Contract', '4': 'Degree Certificate',
      'passport': 'Passport', 'Passport': 'Passport',
      'degree_certificate': 'Degree Certificate', 'Degree Certificate': 'Degree Certificate',
      'power_of_attorney': 'Power of Attorney', 'Power of Attorney': 'Power of Attorney',
      'job_contract': 'Job Contract', 'Job Contract': 'Job Contract',
      'Passport Photo': 'Passport Photo'
  };

  function resolveDocName(gr) {
      var display = gr.getDisplayValue('u_document_name');
      if (display && display.toString().trim() !== '' && !/^\d+$/.test(display.toString().trim())) {
          return display.toString().trim();
      }
      var raw = gr.getValue('u_document_name');
      if (raw && DOC_NAME_MAP[raw.toString().trim()]) {
          return DOC_NAME_MAP[raw.toString().trim()];
      }
      if (display && display.toString().trim()) {
          return display.toString().trim();
      }
      return 'Required Document';
  }

  // ── Handle document re-upload action ──
  if (input && input.action === 'reupload_document') {
      data.reuploadResult = 'pending';
      try {
          var docGr = new GlideRecord(docTable);
          if (docGr.get(input.docSysId)) {
              // Attach new file using GlideSysAttachment
              var sa = new GlideSysAttachment();
              var mimeType = input.fileType || 'application/pdf';
              sa.writeBase64(docGr, input.fileName, mimeType, input.base64);

              // Also attach to parent case
              var parentCaseSysId = docGr.getValue('u_case');
              if (parentCaseSysId) {
                  var caseGr = new GlideRecord(caseTable);
                  if (caseGr.get(parentCaseSysId)) {
                      sa.writeBase64(caseGr, input.fileName, mimeType, input.base64);
                  }
              }

              // Reset status and notes
              docGr.setValue('u_status', 'uploaded');
              docGr.setValue('u_review_notes', 'Re-uploaded by candidate. Pending caseworker re-verification.');
              docGr.update();

              data.reuploadResult = 'success';
              data.reuploadMessage = 'Document re-uploaded successfully. Pending re-verification.';
          } else {
              data.reuploadResult = 'error';
              data.reuploadMessage = 'Document record not found.';
          }
      } catch (ex) {
          data.reuploadResult = 'error';
          data.reuploadMessage = 'Upload failed: ' + ex.message;
      }
      // Don't return — fall through to reload the document matrix so the UI refreshes
  }

  // ── Case Lookup Chain ──
  var sysId = $sp.getParameter('sys_id');
  var grCase = new GlideRecord(caseTable);
  var found = false;

  // 1. Try by sys_id parameter
  if (sysId && grCase.get(sysId)) {
    found = true;
  }

  // 2. Try by logged-in user's email
  if (!found) {
    var userEmail = gs.getUser().getEmail();
    if (userEmail) {
      grCase = new GlideRecord(caseTable);
      grCase.addQuery('u_candidate_email', userEmail);
      grCase.orderByDesc('sys_created_on');
      grCase.setLimit(1);
      grCase.query();
      if (grCase.next()) {
        found = true;
      }
    }
  }

  // 3. Fallback: latest case
  if (!found) {
    grCase = new GlideRecord(caseTable);
    grCase.orderByDesc('sys_created_on');
    grCase.setLimit(1);
    grCase.query();
    if (grCase.next()) {
      found = true;
    }
  }

  if (found && grCase.isValidRecord()) {
    data.hasRecord = true;
    data.sysId = grCase.getUniqueValue();
    data.number = grCase.getValue('number');
    data.candidateName = grCase.getValue('u_candidate_name') || 'Applicant';
    data.city = grCase.getValue('u_target_city') || 'Germany';
    data.category = grCase.getValue('u_visa_category') || 'EU Blue Card';
    data.state = grCase.getDisplayValue('state') || 'Open';
    data.feeStatus = grCase.getValue('u_fee_status') || 'Pending';
    data.clearanceId = grCase.getValue('u_approval_number');
    data.passportNumber = grCase.getValue('u_passport_number');

    // Alias clearanceId to govApprovalNumber for the HTML template logic
    data.govApprovalNumber = grCase.getValue('u_approval_number') || '';

    var stateVal = (grCase.getValue('state') || '').toString();
    data.stateKey = (data.state || '').toLowerCase().replace(/\s+/g, '_');

    // Percentage Calculation:
    // State 3 (Closed Complete) or 11 (Pre-Approved) -> 100%
    // State 10 (Government Review) -> 80%
    // State 9 (Document Check) -> 50%
    // State 1 (Open) / Default -> 25%
    if (stateVal === '11') {
      data.percent = 100;
      data.stageIndex = 4;
    } else if (stateVal === '2') {
      data.percent = 25;
      data.stageIndex = 2;
    } else if (stateVal === '9') {
      data.percent = 50;
      data.stageIndex = 3;
    } else if (stateVal === '10') {
      data.percent = 80;
      data.stageIndex = 3;
    } else if (stateVal === '15') {
      data.percent = 100;
      data.stageIndex = 2;
    } else {
      data.percent = 10;
      data.stageIndex = 1;
    } 

    // ── Load Document Matrix ──
    data.documents = [];
    var grDoc = new GlideRecord(docTable);
    grDoc.addQuery('u_case', data.sysId);
    grDoc.orderBy('sys_created_on');
    grDoc.query();

    while (grDoc.next()) {
      var docStatusDisplay = grDoc.getDisplayValue('u_status') || 'Submitted';
      var docStatusRaw = (grDoc.getValue('u_status') || 'submitted').toLowerCase();
      var docLabel = resolveDocName(grDoc);

      data.documents.push({
        sys_id: grDoc.getUniqueValue(),
        name: docLabel.toString().trim() || 'Required Document',
        status: docStatusDisplay.toString(),
        statusKey: docStatusRaw.replace(/\s+/g, '_'),
        notes: (grDoc.getValue('u_review_notes') || 'Pending initial caseworker verification').toString()
      });
    }
  } else {
    data.hasRecord = false;
  }
})();
